<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;use Illuminate\Support\Facades\{DB,Hash};use App\Models\User;use App\Services\Operations;
class CreateAdmin extends Command {
 protected $signature='northbyte:admin {email} {--name=} {--role=super_admin} {--promote : Explicitly update an existing account}';
 protected $description='Provision an administrative user using an explicit password from a secret prompt or NEW_ADMIN_PASSWORD.';
 public function handle():int{$email=strtolower($this->argument('email'));$role=$this->option('role');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||!in_array($role,['super_admin','admin','team_member'])){$this->error('A valid email and administrative role are required.');return 1;}$existing=User::where('email',$email)->first();if($existing&&!$this->option('promote')){$this->error('Account exists. Use --promote explicitly to change it.');return 1;}$name=$this->option('name')?:$this->ask('Full name');$password=getenv('NEW_ADMIN_PASSWORD')?:$this->secret('Password (12+ characters)');if(!$name||!is_string($password)||mb_strlen($password)<12){$this->error('Name and a password of at least 12 characters are required.');return 1;}if(!getenv('NEW_ADMIN_PASSWORD')&&$password!==$this->secret('Confirm password')){$this->error('Passwords do not match.');return 1;}$user=$existing??new User();DB::transaction(function()use($user,$email,$name,$password,$role){$user->fill(['email'=>$email,'name'=>$name,'password'=>Hash::make($password),'role'=>$role,'status'=>'active','permissions'=>null])->save();DB::table('sessions')->where('user_id',$user->id)->delete();Operations::log(null,'team.provisioned','user',$user->id,['role'=>$role]);});$this->info('Administrative account provisioned. No credentials were logged.');return 0;}
}
